// Command yamlprobe checks whether an anchored truncated scalar can
// reach a checked field through an alias or a merge key, and what an
// omitted optional field with a trailing comment parses to.
package main

import (
	"fmt"

	"gopkg.in/yaml.v3"
)

type evidence struct {
	Name   string `yaml:"name"`
	Status string `yaml:"status"`
}

type result struct {
	Mission  string     `yaml:"mission"`
	Author   string     `yaml:"author"`
	Prose    string     `yaml:"prose,omitempty"`
	Evidence []evidence `yaml:"evidence"`
}

const viaAlias = `mission: m-2026-09-10-001
author: &claim PR #515 merged, 6/6 checks green
evidence:
  - name: *claim
    status: pass
`

const viaMerge = `defaults: &d
  name: PR #515 merged, 6/6 checks green
  status: pass
mission: m-2026-09-10-001
author: bwk
evidence:
  - <<: *d
`

const emptyProse = `mission: m-2026-09-10-001
author: bwk
prose: # no narrative this round
evidence:
  - name: "make check"
    status: pass
`

func decode(label, src string) {
	var r result
	if err := yaml.Unmarshal([]byte(src), &r); err != nil {
		fmt.Printf("%s: unmarshal error: %v\n", label, err)
		return
	}
	fmt.Printf("%s: author=%q prose=%q evidence=%+v\n", label, r.Author, r.Prose, r.Evidence)

	var doc yaml.Node
	if err := yaml.Unmarshal([]byte(src), &doc); err != nil {
		fmt.Printf("%s: node unmarshal error: %v\n", label, err)
		return
	}
	walk(&doc, 1)
}

func walk(n *yaml.Node, depth int) {
	fmt.Printf("%*skind=%d style=%d tag=%s value=%q comment=%q\n",
		depth*2, "", n.Kind, n.Style, n.Tag, n.Value, n.LineComment)
	for _, c := range n.Content {
		walk(c, depth+1)
	}
}

func main() {
	decode("alias", viaAlias)
	fmt.Println()
	decode("merge", viaMerge)
	fmt.Println()
	decode("empty-prose", emptyProse)
}

