// Command yamlprobe checks where yaml.v3 attaches a trailing comment
// when the key has no value: on the key node or on the null value node.
package main

import (
	"fmt"

	"gopkg.in/yaml.v3"
)

var srcs = map[string]string{
	"mapping key, no value":   "prose: # no narrative this round\n",
	"mapping key, spaces":     "prose:    # no narrative\n",
	"sequence item, no value": "open_questions:\n  - # nothing to ask\n",
	"nested key, no value":    "evidence:\n  - name: # the check I ran\n    status: pass\n",
	"empty quoted plus note":  "prose: \"\" # deliberately blank\n",
}

func walk(n *yaml.Node, depth int) {
	fmt.Printf("%*skind=%d style=%d tag=%-7s value=%-12q comment=%q\n",
		depth*2+2, "", n.Kind, n.Style, n.Tag, n.Value, n.LineComment)
	for _, c := range n.Content {
		walk(c, depth+1)
	}
}

func main() {
	for _, name := range []string{
		"mapping key, no value", "mapping key, spaces",
		"sequence item, no value", "nested key, no value",
		"empty quoted plus note",
	} {
		fmt.Printf("%s:\n", name)
		var doc yaml.Node
		if err := yaml.Unmarshal([]byte(srcs[name]), &doc); err != nil {
			fmt.Printf("  unmarshal error: %v\n", err)
			continue
		}
		walk(&doc, 0)
		fmt.Println()
	}
}

